package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.JdbcFrozenInputs;
import com.lianxibu.site.service.jobs.ResultApplicationService.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.*;
import tools.jackson.databind.json.JsonMapper;

/** Actual native current leaf projections; new batch model/typed input remain explicit pure fictional values. */
class CatalogVersionJudgmentBatchValueTest extends CatalogVersionJudgmentValueTest {
    @Test void FourCategorySingleBatchMatchesTheOriginalExactSingleValue(){for(String cat:List.of("agent","skill","workflow","model")){initialize(cat,false);var p=projection();var i=input(p);var r=result(i,payload(p,true));var batch=CatalogVersionJudgmentValue.createAll(Map.of(p.memberId(),p),i,r);assertEquals(1,batch.size());assertEquals(CatalogVersionJudgmentValue.create(p,i,r).orElseThrow().hash(),batch.get(p.memberId()).hash());assertThrows(RuntimeException.class,batch::clear);assertEquals(1,f.sends);}}
    @Test void UnknownNewReviewOtherCandidateAndFirstLedgerOmittedCaptureDoNotManufactureValues(){var p=projection();var i=input(p);for(String decision:List.of("new","needs_review","existing")){var payload=payload(p,false);var item=(ObjectNode)payload.get("items").get(0);item.put("decision",decision).putNull("version_changed").putNull("previous_evidence_ref").putNull("new_evidence_ref");if(decision.equals("existing"))item.put("candidate_entity_id","fictional-other-entity");else item.putNull("candidate_entity_id");assertTrue(CatalogVersionJudgmentValue.createAll(Map.of(p.memberId(),p),i,result(i,payload)).isEmpty());}assertTrue(CatalogVersionJudgmentValue.createAll(Map.of(),i,result(i,payload(p,true))).isEmpty());}
    @Test void ActualHundredCurrentLeafProjectionsBecomeOneCompletePureBatchWithoutPerMemberResultReparse(){var projections=new TreeMap<String,CatalogVersionQualificationProjection.Projection>();var candidates=new HashMap<String,Set<String>>();var qualifications=new HashMap<String,FrozenCatalogVersionQualifications.Qualification>();for(int n=0;n<100;n++){String id=String.format(Locale.ROOT,"fictional-batch-%03d",n);f.jdbc.update("INSERT INTO source_run_items SELECT ?,run_id,source_id,revision,category,created_at,terminal_state,state,projection_decision,effective_valid,evidence_json,evidence_hash,entity_id,? FROM source_run_items WHERE id='fictional-current-item'",id,"fictional-batch-source-"+n);var p=service.readProjection(f.category,"fictional-entity","fictional-analysis",id,f.clock.instant()).orElseThrow();projections.put(id,p);candidates.put(id,Set.of(p.entityId()));qualifications.put(id,p.resultConstraint());}var base=input(projection());var i=new Input(base.rootId(),base.attemptId(),base.stage(),base.generation(),base.inputHash(),base.expectedRootRevision(),base.expectedContentRevision(),Set.copyOf(projections.keySet()),Map.copyOf(candidates),Set.of(),Set.of(),Set.copyOf(projections.keySet()),null,null,null,"1","2",Map.copyOf(qualifications));var payload=JsonMapper.shared().createObjectNode().put("kind","dedup").put("dedup_result_version","2").put("summary","Fictional complete 100 leaf model decisions");var items=payload.putArray("items");projections.forEach((id,p)->items.add(payload(p,true).get("items").get(0)));var valid=result(i,payload);var full=CatalogVersionJudgmentValue.createAll(projections,i,valid);assertEquals(100,full.size());assertTrue(full.containsKey("fictional-batch-099"));assertEquals(1,full.values().stream().map(CatalogVersionJudgmentValue.Value::judgmentKey).distinct().count());payload.put("summary","Fictional caller changed");assertEquals(valid.resultHash(),CanonicalJson.parse(full.get("fictional-batch-099").json()).get("result_hash").asText());var bad=payload.deepCopy();((ObjectNode)bad.get("items").get(99).get("new_evidence_ref")).put("proof_hash","f".repeat(64));assertThrows(RuntimeException.class,()->CatalogVersionJudgmentValue.createAll(projections,i,new Validated("dedup",JdbcFrozenInputs.canonical(bad),valid.resultHash(),i.inputHash())));assertEquals(1,f.sends);assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));}
    @Test void ForgedValidatedAliasedProjectionAndLaterRefMutationRejectTheWholePureBatch(){var p=projection();var i=input(p);var valid=result(i,payload(p,true));assertThrows(RuntimeException.class,()->CatalogVersionJudgmentValue.createAll(Map.of("fictional-alias",p),i,valid));assertThrows(RuntimeException.class,()->CatalogVersionJudgmentValue.createAll(Map.of(p.memberId(),p),i,new Validated(valid.kind(),valid.payloadJson(),"f".repeat(64),valid.inputHash())));current.put("summary","Fictional later");update();var later=projection();assertThrows(RuntimeException.class,()->CatalogVersionJudgmentValue.createAll(Map.of(p.memberId(),later),i,valid));assertEquals(1,f.sends);}
}
